import java.io.*;import java.util.*;import java.nio.file.*;
import app.hiro.oneback.patches.OneBackPatch;
import app.morphe.patcher.util.proxy.mutableTypes.*;
import com.android.tools.smali.dexlib2.*;import com.android.tools.smali.dexlib2.iface.*;import com.android.tools.smali.dexlib2.iface.instruction.*;import com.android.tools.smali.dexlib2.iface.reference.*;
import com.android.tools.smali.dexlib2.builder.*;import com.android.tools.smali.dexlib2.builder.instruction.*;import com.android.tools.smali.dexlib2.immutable.*;import com.android.tools.smali.dexlib2.writer.pool.*;import com.android.tools.smali.dexlib2.writer.io.*;
/** Actual v447 executable-code audit. Dexlib normalizes supplied debug line PCs that
 * point inside multi-unit invokes; canonical comparisons therefore omit debug
 * items only and preserve instructions, registers, try blocks and method metadata. */
public final class InstagramDispatcherAudit {
 static int checks;
 static void check(boolean pass,String why){checks++;if(!pass)throw new AssertionError(why);}
 static Map<String,ClassDef> read(String path)throws Exception{Map<String,ClassDef> out=new LinkedHashMap<>();MultiDexContainer<? extends DexFile> dex=DexFileFactory.loadDexContainer(new File(path),Opcodes.getDefault());for(String entry:dex.getDexEntryNames())for(ClassDef c:dex.getEntry(entry).getDexFile().getClasses())if(Arrays.asList("LX/01h;","LX/0Ok;","Landroidx/activity/ComponentActivity;","Lcom/instagram/mainactivity/InstagramMainActivity;").contains(c.getType()))out.put(c.getType(),c);return out;}
 static String key(Method m){return m.getName()+m.getParameterTypes()+m.getReturnType();}
 static Method find(ClassDef c,String name){for(Method m:c.getMethods())if(m.getName().equals(name))return m;throw new AssertionError(name);}
 static List<Instruction> ins(Method m){List<Instruction> out=new ArrayList<>();for(Instruction i:m.getImplementation().getInstructions())out.add(i);return out;}
 static MethodReference ref(Instruction i){return (MethodReference)((ReferenceInstruction)i).getReference();}
 static byte[] bytes(Method m)throws Exception{if(m.getImplementation()!=null)m=new ImmutableMethod(m.getDefiningClass(),m.getName(),m.getParameters(),m.getReturnType(),m.getAccessFlags(),m.getAnnotations(),m.getHiddenApiRestrictions(),new ImmutableMethodImplementation(m.getImplementation().getRegisterCount(),m.getImplementation().getInstructions(),m.getImplementation().getTryBlocks(),Collections.emptyList()));ClassDef c=new ImmutableClassDef(m.getDefiningClass(),1,"Ljava/lang/Object;",Collections.emptyList(),null,Collections.emptySet(),Collections.emptyList(),Collections.singleton(m));MemoryDataStore store=new MemoryDataStore();DexPool.writeTo(store,new ImmutableDexFile(Opcodes.getDefault(),Collections.singleton(c)));byte[] b=Arrays.copyOf(store.getBuffer(),store.getSize());store.close();return b;}
 static int target(List<Instruction> b,int n){int pc=0;for(int i=0;i<n;i++)pc+=b.get(i).getCodeUnits();pc+=((OffsetInstruction)b.get(n)).getCodeOffset();int address=0;for(int i=0;i<b.size();i++){if(address==pc)return i;address+=b.get(i).getCodeUnits();}throw new AssertionError("branch target");}
 static void gate(Method m,String hook){List<Instruction>b=ins(m);check(b.get(0).getOpcode()==Opcode.INVOKE_STATIC&&ref(b.get(0)).getName().equals(hook),"entry runtime call "+hook);check(((FiveRegisterInstruction)b.get(0)).getRegisterC()==4,"exact dispatcher receiver");check(target(b,2)==4,"false reaches unchanged native entry");check(b.get(3).getOpcode()==Opcode.RETURN_VOID,"true returns before native callback selection");}
 static Method restored(Method m){MutableMethodImplementation body=new MutableMethodImplementation(m.getImplementation());String owner=m.getDefiningClass(),name=m.getName();if(owner.equals("LX/01h;")&&(name.equals("A00")||name.equals("A04")))for(int n=0;n<4;n++)body.removeInstruction(0);else if(owner.equals("Landroidx/activity/ComponentActivity;")&&name.equals("CoN"))body.removeInstruction(4);else if(owner.equals("LX/0Ok;")&&name.equals("invoke")){for(int n=0;n<3;n++)body.removeInstruction(55);for(int n=0;n<3;n++)body.removeInstruction(41);}return new ImmutableMethod(owner,name,m.getParameters(),m.getReturnType(),m.getAccessFlags(),m.getAnnotations(),m.getHiddenApiRestrictions(),body);}
 public static void main(String[] args)throws Exception{
  Map<String,ClassDef> original=read(args[0]);check(original.size()==4,"all actual APK dispatcher classes present");Map<String,MutableClass> changed=new LinkedHashMap<>();Map<String,Integer>counts=new LinkedHashMap<>();
  OneBackPatch.applyInstagramDispatcher(original,t->changed.computeIfAbsent(t,k->new MutableClass(original.get(k))),counts);
  check(changed.size()==3&&counts.size()==5,"only three intended classes and five hook kinds");
  MemoryDataStore store=new MemoryDataStore();DexPool.writeTo(store,new ImmutableDexFile(Opcodes.getDefault(),changed.values()));byte[] dex=Arrays.copyOf(store.getBuffer(),store.getSize());store.close();Files.write(Paths.get(args[1]),dex);
  Map<String,ClassDef> emitted=read(args[1]);gate(find(emitted.get("LX/01h;"),"A04"),"tryInstagramDispatcherBack");gate(find(emitted.get("LX/01h;"),"A00"),"cancelInstagramDispatcherGesture");
  List<Instruction> getter=ins(find(emitted.get("Landroidx/activity/ComponentActivity;"),"CoN"));FiveRegisterInstruction bind=(FiveRegisterInstruction)getter.get(4);check(ref(getter.get(4)).getName().equals("bindInstagramDispatcher")&&bind.getRegisterC()==1&&bind.getRegisterD()==0,"getter binds actual Activity and dispatcher return");
  List<Instruction> gesture=ins(find(emitted.get("LX/0Ok;"),"invoke"));check(target(gesture,39)==41,"start incoming branch passes hook");check(ref(gesture.get(41)).getName().equals("startInstagramDispatcherGesture")&&((FiveRegisterInstruction)gesture.get(41)).getRegisterC()==3,"start actual dispatcher");check(ref(gesture.get(55)).getName().equals("progressInstagramDispatcherGesture")&&((FiveRegisterInstruction)gesture.get(55)).getRegisterC()==0,"progress actual dispatcher");check(target(gesture,43)==77&&target(gesture,57)==77,"suppressed start and progress go to Unit return");check(gesture.get(77).getOpcode()==Opcode.SGET_OBJECT&&gesture.get(78).getOpcode()==Opcode.RETURN_OBJECT,"Unit return is preserved");
  int restoredMethods=0,unrelated=0;for(ClassDef c:emitted.values()){Map<String,Method> prior=new HashMap<>();for(Method m:original.get(c.getType()).getMethods())prior.put(key(m),m);for(Method m:c.getMethods()){Method old=prior.remove(key(m));check(old!=null,"no unexpected methods");boolean touched=(c.getType().equals("LX/01h;")&&(m.getName().equals("A00")||m.getName().equals("A04")))||(c.getType().equals("LX/0Ok;")&&m.getName().equals("invoke"))||(c.getType().equals("Landroidx/activity/ComponentActivity;")&&m.getName().equals("CoN"));if(touched){check(Arrays.equals(bytes(old),bytes(restored(m))),"native method body is byte-exact after stripping gates: "+m);restoredMethods++;}else{check(Arrays.equals(bytes(old),bytes(m)),"unrelated method byte-exact: "+m);unrelated++;}}check(prior.isEmpty(),"no removed methods");}
  Map<String,ClassDef> bad=new LinkedHashMap<>(original);MutableClass broken=new MutableClass(original.get("LX/01h;"));MutableMethod commit=(MutableMethod)find(broken,"A04");Reference r=((ReferenceInstruction)commit.getImplementation().getInstructions().get(0)).getReference();commit.getImplementation().replaceInstruction(0,new BuilderInstruction22c(Opcode.IGET_OBJECT,1,3,r));bad.put("LX/01h;",broken);final int[]mutations={0};boolean refused=false;try{OneBackPatch.applyInstagramDispatcher(bad,t->{mutations[0]++;return new MutableClass(bad.get(t));},new HashMap<>());}catch(IllegalStateException expected){refused=true;}check(refused&&mutations[0]==0,"changed register dataflow refused before all mutation");
  System.out.println("PASS actual v447 dispatcher: "+checks+" assertions; "+restoredMethods+" native executable bodies restored byte-exact; "+unrelated+" unrelated executable methods byte-exact (debug omitted); "+counts+". Static DEX validation only; no Android device execution.");
 }
}
